import { setupServer } from 'msw/node'

// Handlers ficam vazios aqui; cada teste registra os seus com servidor.use(...).
export const servidor = setupServer()

export class ErroApi extends Error {
  constructor(status, codigo, mensagem) {
    super(mensagem || codigo)
    this.status = status
    this.codigo = codigo
  }
}

export async function chamarApi(caminho, { metodo = 'GET', usuarioId, corpo } = {}) {
  const cabecalhos = { 'Content-Type': 'application/json' }
  if (usuarioId) cabecalhos['X-Usuario'] = usuarioId

  const resposta = await fetch(caminho, {
    method: metodo,
    headers: cabecalhos,
    body: corpo === undefined ? undefined : JSON.stringify(corpo),
  })

  const dados = resposta.status === 204 ? null : await resposta.json()

  if (!resposta.ok) {
    throw new ErroApi(resposta.status, dados?.erro, dados?.mensagem)
  }

  return dados
}

import { render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { http, HttpResponse } from 'msw'
import { describe, expect, it } from 'vitest'
import { servidor } from '../../testes/servidor.js'
import { ProgramacaoPorDia } from './ProgramacaoPorDia.jsx'

function atividade(sobrepor = {}) {
  return {
    id: 'atv_11111111',
    titulo: 'IA hoje',
    tipo: 'palestra',
    salaId: 'sala-101',
    vagas: 40,
    encontros: [{ id: 'enc_11111111', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' }],
    cargaHorariaMinutos: 120,
    situacao: 'prevista',
    ocupadas: 0,
    vagasRestantes: 40,
    emEspera: 0,
    ...sobrepor,
  }
}

describe('ProgramacaoPorDia', () => {
  it('lista as atividades do dia inicial do evento', async () => {
    servidor.use(
      http.get('/atividades', ({ request }) => {
        const url = new URL(request.url)
        expect(url.searchParams.get('dia')).toBe('2026-10-19')
        return HttpResponse.json([atividade()])
      }),
    )

    render(<ProgramacaoPorDia usuarioId="p-carla" />)

    expect(await screen.findByText('IA hoje')).toBeInTheDocument()
  })

  it('mostra mensagem quando não há atividades no dia', async () => {
    servidor.use(http.get('/atividades', () => HttpResponse.json([])))

    render(<ProgramacaoPorDia usuarioId="p-carla" />)

    expect(await screen.findByText(/nenhuma atividade/i)).toBeInTheDocument()
  })

  it('filtra por tipo ao escolher no seletor', async () => {
    let ultimoTipo = null
    servidor.use(
      http.get('/atividades', ({ request }) => {
        const url = new URL(request.url)
        ultimoTipo = url.searchParams.get('tipo')
        return HttpResponse.json(
          ultimoTipo === 'minicurso' ? [atividade({ id: 'atv_22222222', titulo: 'Flutter do zero', tipo: 'minicurso' })] : [atividade()],
        )
      }),
    )

    render(<ProgramacaoPorDia usuarioId="p-carla" />)
    await screen.findByText('IA hoje')

    await userEvent.selectOptions(screen.getByLabelText(/tipo/i), 'minicurso')

    expect(await screen.findByText('Flutter do zero')).toBeInTheDocument()
    expect(ultimoTipo).toBe('minicurso')
  })

  it('navega para o próximo dia e desabilita o botão no último dia', async () => {
    const dias = []
    servidor.use(
      http.get('/atividades', ({ request }) => {
        const url = new URL(request.url)
        dias.push(url.searchParams.get('dia'))
        return HttpResponse.json([])
      }),
    )

    render(<ProgramacaoPorDia usuarioId="p-carla" />)
    await screen.findByText(/nenhuma atividade/i)

    const proximo = screen.getByRole('button', { name: /próximo dia/i })
    const anterior = screen.getByRole('button', { name: /dia anterior/i })

    expect(anterior).toBeDisabled()

    await userEvent.click(proximo)
    await userEvent.click(proximo)
    await userEvent.click(proximo)
    await userEvent.click(proximo)

    await waitFor(() => expect(proximo).toBeDisabled())
    expect(dias.at(-1)).toBe('2026-10-23')
  })

  it('chama onSelecionarAtividade ao clicar em uma atividade', async () => {
    servidor.use(http.get('/atividades', () => HttpResponse.json([atividade()])))

    let selecionada = null
    render(<ProgramacaoPorDia usuarioId="p-carla" onSelecionarAtividade={(id) => (selecionada = id)} />)

    const item = await screen.findByRole('button', { name: /ia hoje/i })
    await userEvent.click(item)

    expect(selecionada).toBe('atv_11111111')
  })
})

// Semana Acadêmica: 19 a 23/10/2026 (spec M1 §1).
export const DIAS_DO_EVENTO = ['2026-10-19', '2026-10-20', '2026-10-21', '2026-10-22', '2026-10-23']

export function formatarDia(dia) {
  const [ano, mes, diaDoMes] = dia.split('-')
  return `${diaDoMes}/${mes}/${ano}`
}

const RÓTULOS = {
  prevista: 'Prevista',
  em_andamento: 'Em andamento',
  encerrada: 'Encerrada',
  cancelada: 'Cancelada',
}

export function rotuloDaSituacao(situacao) {
  return RÓTULOS[situacao] ?? situacao
}

const RÓTULOS_TIPO = {
  palestra: 'Palestra',
  minicurso: 'Minicurso',
}

export function rotuloDoTipo(tipo) {
  return RÓTULOS_TIPO[tipo] ?? tipo
}

import { useEffect, useState } from 'react'
import { chamarApi } from '../../api/cliente.js'
import { DIAS_DO_EVENTO, formatarDia } from './dias.js'
import { rotuloDaSituacao, rotuloDoTipo } from './situacao.js'

export function ProgramacaoPorDia({ usuarioId, onSelecionarAtividade }) {
  const [indiceDoDia, setIndiceDoDia] = useState(0)
  const [tipo, setTipo] = useState('')
  const [atividades, setAtividades] = useState(null)
  const [erro, setErro] = useState(null)

  const dia = DIAS_DO_EVENTO[indiceDoDia]

  useEffect(() => {
    let cancelado = false
    setAtividades(null)
    setErro(null)

    const parametros = new URLSearchParams({ dia })
    if (tipo) parametros.set('tipo', tipo)

    chamarApi(`/atividades?${parametros}`, { usuarioId })
      .then((dados) => {
        if (!cancelado) setAtividades(dados)
      })
      .catch((e) => {
        if (!cancelado) setErro(e)
      })

    return () => {
      cancelado = true
    }
  }, [dia, tipo, usuarioId])

  return (
    <section>
      <h1>Programação</h1>

      <div role="group" aria-label="Navegação por dia">
        <button type="button" onClick={() => setIndiceDoDia((i) => i - 1)} disabled={indiceDoDia === 0}>
          Dia anterior
        </button>
        <span>{formatarDia(dia)}</span>
        <button
          type="button"
          onClick={() => setIndiceDoDia((i) => i + 1)}
          disabled={indiceDoDia === DIAS_DO_EVENTO.length - 1}
        >
          Próximo dia
        </button>
      </div>

      <label>
        Tipo
        <select value={tipo} onChange={(e) => setTipo(e.target.value)}>
          <option value="">Todos</option>
          <option value="palestra">Palestra</option>
          <option value="minicurso">Minicurso</option>
        </select>
      </label>

      {erro && <p role="alert">Não foi possível carregar a programação.</p>}

      {atividades && atividades.length === 0 && <p>Nenhuma atividade neste dia.</p>}

      {atividades && atividades.length > 0 && (
        <ul>
          {atividades.map((atividade) => (
            <li key={atividade.id}>
              <button type="button" onClick={() => onSelecionarAtividade?.(atividade.id)}>
                <strong>{atividade.titulo}</strong> — {rotuloDoTipo(atividade.tipo)} — {rotuloDaSituacao(atividade.situacao)}
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}

